const uint8_t *font_text_bitmap(char c)
{
    uint16_t idx = (uint16_t)(uint8_t)c;
    if (idx < FONT_TEXT_FIRST_CHAR || idx > FONT_TEXT_LAST_CHAR) {
        return (const uint8_t *)0;
    }
    return s_text_bitmaps[idx - FONT_TEXT_FIRST_CHAR];
}

const uint8_t *font_text_symbol_bitmap(uint8_t sym)
{
    if (sym >= FONT_TEXT_SYM_COUNT) {
        return (const uint8_t *)0;
    }
    return s_symbol_bitmaps[sym];
}

uint16_t font_text_width(void)
{
    return FONT_TEXT_WIDTH;
}

uint16_t font_text_height(void)
{
    return FONT_TEXT_HEIGHT;
}
